head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.TR_JOB;
scwin.vScrenID = "ULDSTF41531.xml";
scwin.vIsurCd = "";
scwin.vBackListDesignDD = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_CoSearch.src = "../img/btn_search.gif";
        img_CoSearch.setDisabled(false);
    } else if (initTyp == "X") {
        img_CoSearch.src = "../img/btn_search_d.gif";
        img_CoSearch.setDisabled(true);
        btn_Search.src = "../img/btn_select_d.gif";
        btn_Search.setDisabled(true);
        img_BACKLIST_DESIGN_DD.src = "../img/icn_calendar_d.gif";
        img_BACKLIST_DESIGN_DD.setDisabled(true);
    }
};
scwin.fn_SetComboCode = function() {
    var strCode = "1^합병,2^포괄적 주식교환,3^영업양수,4^자산양수,5^현물출자,6^기타";
    cmb_BACKLIST_ADM_TP_CD.CBData = strCode;
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_BACKLIST_DISCLS_DD) == "") {
        $c.win.alert("[우회상장 공시일]을 입력하세요.");
        edt_BACKLIST_DISCLS_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_BACKLIST_DESIGN_DD) == "") {
        $c.win.alert("[우회상장 지정일]을 입력하세요.");
        edt_BACKLIST_DESIGN_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_BACKLIST_ADM_TP_CD) == "") {
        $c.win.alert("[우회상장 유형]을 선택하세요.");
        cmb_BACKLIST_ADM_TP_CD.focus();
        return false;
    }
    return true;
};
scwin.fn_setDataItem = function() {
    dts_Item.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    dts_Item.setCellData(1, "BACKLIST_DESIGN_DD", $c.stf.getObjectValue(edt_BACKLIST_DESIGN_DD));
    dts_Item.setCellData(1, "BACKLIST_DISCLS_DD", $c.stf.getObjectValue(edt_BACKLIST_DISCLS_DD));
    dts_Item.setCellData(1, "BACKLIST_ADM_TP_CD", $c.stf.getObjectValue(cmb_BACKLIST_ADM_TP_CD));
    dts_Item.setCellData(1, "BACKLIST_ACNTG_CORP_NM", $c.stf.getObjectValue(txb_BACKLIST_ACNTG_CORP_NM));
    dts_Item.setCellData(1, "BACKLIST_AGNCCOM_NM", $c.stf.getObjectValue(txb_BACKLIST_AGNCCOM_NM));
    dts_Item.setCellData(1, "EXT_VALU_INST_NM", $c.stf.getObjectValue(txb_EXT_VALU_INST_NM));
    dts_Item.setCellData(1, "LIST_CORP_ASST_TOTAMT", $c.stf.getObjectValue(edt_LIST_CORP_ASST_TOTAMT));
    dts_Item.setCellData(1, "LIST_CORP_SALES", $c.stf.getObjectValue(edt_LIST_CORP_SALES));
    dts_Item.setCellData(1, "LIST_CORP_DEBT_TOTAMT", $c.stf.getObjectValue(edt_LIST_CORP_DEBT_TOTAMT));
    dts_Item.setCellData(1, "LIST_CORP_OPERPROFT_AMT", $c.stf.getObjectValue(edt_LIST_CORP_OPERPROFT_AMT));
    dts_Item.setCellData(1, "LIST_CORP_CAP", $c.stf.getObjectValue(edt_LIST_CORP_CAP));
    dts_Item.setCellData(1, "LIST_CORP_ORDNINCM_AMT", $c.stf.getObjectValue(edt_LIST_CORP_ORDNINCM_AMT));
    dts_Item.setCellData(1, "LIST_CORP_CAP_TOTAMT", $c.stf.getObjectValue(edt_LIST_CORP_CAP_TOTAMT));
    dts_Item.setCellData(1, "LIST_CORP_NETINCM", $c.stf.getObjectValue(edt_LIST_CORP_NETINCM));
    dts_Item.setCellData(1, "NLIST_CORP_NM", $c.stf.getObjectValue(txb_NLIST_CORP_NM));
    dts_Item.setCellData(1, "NLIST_ACNTG_CORP_NM", $c.stf.getObjectValue(txb_NLIST_ACNTG_CORP_NM));
    dts_Item.setCellData(1, "NLIST_CORP_ASST_TOTAMT", $c.stf.getObjectValue(edt_NLIST_CORP_ASST_TOTAMT));
    dts_Item.setCellData(1, "NLIST_CORP_SALES", $c.stf.getObjectValue(edt_NLIST_CORP_SALES));
    dts_Item.setCellData(1, "NLIST_CORP_DEBT_TOTAMT", $c.stf.getObjectValue(edt_NLIST_CORP_DEBT_TOTAMT));
    dts_Item.setCellData(1, "NLIST_CORP_OPERPROFT_AMT", $c.stf.getObjectValue(edt_NLIST_CORP_OPERPROFT_AMT));
    dts_Item.setCellData(1, "NLIST_CORP_CAP", $c.stf.getObjectValue(edt_NLIST_CORP_CAP));
    dts_Item.setCellData(1, "NLIST_CORP_ORDNINCM_AMT", $c.stf.getObjectValue(edt_NLIST_CORP_ORDNINCM_AMT));
    dts_Item.setCellData(1, "NLIST_CORP_CAP_TOTAMT", $c.stf.getObjectValue(edt_NLIST_CORP_CAP_TOTAMT));
    dts_Item.setCellData(1, "NLIST_CORP_NETINCM", $c.stf.getObjectValue(edt_NLIST_CORP_NETINCM));
};

/**
 * 우회상장회사 정보조회
 */
scwin.fn_search_sync = function() {
    var pIsurCd = $c.stf.getObjectValue(txb_ISUR_CD);
    var pComNm = $c.stf.getObjectValue(txb_COM_NM);
    var pDesignDd = $c.stf.getObjectValue(edt_BACKLIST_DESIGN_DD);
    var pDisclsDd = $c.stf.getObjectValue(edt_BACKLIST_DISCLS_DD);
    var pAdmTpCd = $c.stf.getObjectValue(cmb_BACKLIST_ADM_TP_CD);
    var url = "/RepMajagnt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchBackListComDetail";
    url += "&inputMessageId=BACKLIST_COM_INPUT_OUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&BACKLIST_DESIGN_DD=" + $c.stf.getObjectValue(edt_BACKLIST_DESIGN_DD);
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "" || $c.stf.getObjectValue(edt_BACKLIST_DESIGN_DD) == "") {
        $c.win.alert("[해당회사는 입력 데이터가 없습니다.]");
        dts_Item.insertRow();
        txb_ISUR_CD.setValue(pIsurCd);
        txb_COM_NM.setValue(pComNm);
        edt_BACKLIST_DESIGN_DD.setValue(pDesignDd);
        edt_BACKLIST_DISCLS_DD.setValue(pDisclsDd);
        cmb_BACKLIST_ADM_TP_CD.setSelectedIndex(eval(pAdmTpCd - 1));
    }
};



/**
 * 신규입력시 중복입력여부를 체크
 */
scwin.fn_checkDoubleInput = function() {
    var url = "/RepMajagnt.do?method=selectBackListDoubleCheck&inputMessageId=BACKLIST_COM_DOUBLE_INPUT_OUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&BACKLIST_DESIGN_DD=" + $c.stf.getObjectValue(edt_BACKLIST_DESIGN_DD);
    dts_DoubleChk.DataID = encodeURI(url);
    dts_DoubleChk.Reset();
    var str = dts_DoubleChk.getCellData(1, "DBINPUT_YN");
    if (str == 'Y') {
        $c.win.alert("[해당종목은 이미 동일한 우회상장지정일에 입력 데이터가 있습니다.]");
        return false;
    } else if (str == 'N') {
        return true;
    }
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if ($c.pre_newlisting.fn_checkDoubleInput()) {
            scwin.fn_trs(TR_JOB_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_DELETE);
    }
};
scwin.fn_trs = function(jobType) {
    var vScrenTpCD;
    if (scwin.TR_JOB == 'I') {
        vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == 'D') {
        vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    scwin.fn_setDataItem();
    trs_Save.Action = $c.lc.fn_encodeNSession("/RepMajagnt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenTpCD + "&method=saveBackListComAction");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Parameters = "JOB_TYPE=" + jobType;
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.img_CoSearch_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.img_BACKLIST_DISCLS_DD_onclick = function() {
    popUpCalendar2(edt_BACKLIST_DISCLS_DD);
};
scwin.img_BACKLIST_DESIGN_DD_onclick = function() {
    popUpCalendar2(edt_BACKLIST_DESIGN_DD);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_search_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_DoubleChk_OnLoadError = function() {
    $c.stf.alert_error(dts_DoubleChk);
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_initForm("X");
    buttonSet.setUpdateStatus();
    scwin.fn_parentRefresh();
    if (scwin.TR_JOB == "D") {
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_search_sync();
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_SetComboCode();
    var parentWin = $c.frame.path("../");
    scwin.vIsurCd = parentWin.clickIsurCd;
    scwin.vBackListDesignDD = parentWin.clickBackListDesignDD;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제

    if (scwin.vIsurCd == "") {
        scwin.fn_initForm("C");
        dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BACKLIST_COM_INPUT_OUT";
        dts_Item.reset();
        dts_Item.insertRow();
    } else {
        txb_ISUR_CD.setValue(scwin.vIsurCd);
        edt_BACKLIST_DESIGN_DD.setValue(scwin.vBackListDesignDD);
        edt_BACKLIST_DESIGN_DD.setReadOnly(true);
        scwin.fn_initForm("X");
        buttonSet.setUpdateStatus();
        scwin.fn_search_sync();
    }
};
